-- ----------------------------
-- Table structure for m_raw_material
-- ----------------------------
DROP TABLE IF EXISTS `m_raw_material`;
CREATE TABLE `m_raw_material`  (
  `material_id` bigint NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `material_code` varchar(60) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Kode',
  `material_name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Nama bahan baku',
  `item_type` enum('MATERIAL','SERVICE','FREE_SAMPLE') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'MATERIAL' COMMENT 'Jenis item: MATERIAL, SERVICE, atau FREE_SAMPLE',
  `category1` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `category2` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `category3` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `category4` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `category5` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `description` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT 'Keterangan',
  `brand` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT 'Merek',
  `color` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT 'warna',
  `gram_weight` int UNSIGNED NULL DEFAULT 0 COMMENT 'gramasi',
  `cm_length` decimal(12, 4) UNSIGNED NULL DEFAULT 0.0000 COMMENT 'panjang in cm',
  `cm_width` decimal(12, 4) UNSIGNED NULL DEFAULT 0.0000 COMMENT 'lebar in cm',
  `mm_thickness` decimal(12, 4) UNSIGNED NULL DEFAULT 0.0000 COMMENT 'ketebalan dalam mm',
  `specification` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT 'spec lain bila non kertas',
  `uom_stock` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT 'satuan stok',
  `uom_purchase` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT 'satuan pembelian',
  `purchasable` tinyint UNSIGNED NOT NULL DEFAULT 1 COMMENT '1=boleh dibeli via purchasing, 0=tidak',
  `uom_usage` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT 'satuan pemakaian',
  `conversion_to_stock` decimal(20, 6) UNSIGNED NULL DEFAULT 1.000000 COMMENT 'konversi dari pembelian ke stok',
  `conversion_to_usage` decimal(20, 6) UNSIGNED NULL DEFAULT NULL COMMENT 'konversi dari stok ke pemakaian',
  `suggest_supplier_id` bigint UNSIGNED NULL DEFAULT NULL COMMENT 'Vendor rekomendasi (bukan final vendor)',
  `tol_purchase` decimal(5, 2) NULL DEFAULT NULL COMMENT 'toleransi pembelian kisaran 0 - 100',
  `free_note` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT 'Keterangan bila item tipe FREE_SAMPLE, alasan atau syarat',
  `min_stock` decimal(20, 4) UNSIGNED NULL DEFAULT 0.0000 COMMENT 'jumlah minim ',
  `max_stock` decimal(20, 4) UNSIGNED NULL DEFAULT NULL COMMENT 'jumlah maks',
  `cur_stock` decimal(20, 4) NULL DEFAULT NULL COMMENT 'current stok saat ini',
  `is_active` tinyint UNSIGNED NULL DEFAULT 1 COMMENT 'active atau tidak',
  `avg_unitprice` decimal(30, 5) NULL DEFAULT NULL COMMENT 'harga perolehan rata-rata',
  `last_unitprice` decimal(30, 5) NULL DEFAULT NULL COMMENT 'harga perolehan terakhir saat beli',
  `def_location_id` bigint UNSIGNED NULL DEFAULT NULL COMMENT 'default location ID',
  `create_log` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `update_log` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `create_by` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `update_by` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `old_item_code` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `old_item_name` varchar(250) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  PRIMARY KEY (`material_id`) USING BTREE,
  UNIQUE INDEX `material_code`(`material_code` ASC) USING BTREE,
  INDEX `fk_rawmat_uom_stock`(`uom_stock` ASC) USING BTREE,
  INDEX `fk_rawmat_uom_purchase`(`uom_purchase` ASC) USING BTREE,
  INDEX `fk_rawmat_uom_usage`(`uom_usage` ASC) USING BTREE,
  CONSTRAINT `fk_rawmat_uom_purchase` FOREIGN KEY (`uom_purchase`) REFERENCES `m_uom` (`uom_code`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `fk_rawmat_uom_stock` FOREIGN KEY (`uom_stock`) REFERENCES `m_uom` (`uom_code`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `fk_rawmat_uom_usage` FOREIGN KEY (`uom_usage`) REFERENCES `m_uom` (`uom_code`) ON DELETE RESTRICT ON UPDATE CASCADE
) ENGINE = InnoDB AUTO_INCREMENT = 5895 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = 'Master bahan baku (kertas, tinta, support material)' ROW_FORMAT = Dynamic;

